{"path": "poker.py", "content": "from collections import Counter

RANKS = {str(n): n for n in range(2, 11)}
RANKS.update({"J": 11, "Q": 12, "K": 13, "A": 14})


def _score(hand):
    cards = hand.split()
    ranks = [RANKS[card[:-1]] for card in cards]
    suits = [card[-1] for card in cards]

    counts = Counter(ranks)
    # Sort ranks by (count, rank) descending, e.g. full house -> [3s..., 2s...]
    grouped = sorted(counts.items(), key=lambda item: (item[1], item[0]), reverse=True)
    shape = [count for _, count in grouped]
    order = [rank for rank, _ in grouped]

    flush = len(set(suits)) == 1
    straight = False
    if len(counts) == 5:
        if order[0] - order[4] == 4:
            straight = True
        elif order == [14, 5, 4, 3, 2]:
            straight = True
            order = [5, 4, 3, 2, 1]

    if straight and flush:
        category = 8
    elif shape == [4, 1]:
        category = 7
    elif shape == [3, 2]:
        category = 6
    elif flush:
        category = 5
    elif straight:
        category = 4
    elif shape == [3, 1, 1]:
        category = 3
    elif shape == [2, 2, 1]:
        category = 2
    elif shape == [2, 1, 1, 1]:
        category = 1
    else:
        category = 0
    return (category, order)


def best_hands(hands):
    scores = [_score(hand) for hand in hands]
    best = max(scores)
    return [hand for hand, score in zip(hands, scores) if score == best]
